package com.aadil.jobtracker.UserController;import com.aadil.jobtracker.UserRepository.SortDirection;import com.aadil.jobtracker.UserRepository.UserSortField;import com.aadil.jobtracker.UserService.UserServiceImp;import com.aadil.jobtracker.Validation.UserRequestDTO;import com.aadil.jobtracker.Validation.UserResponseDTO;import com.aadil.jobtracker.responses.PagedResponse;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.util.List;import java.util.Optional;@RestController@RequestMapping("/users")@Validatedpublic class UserController {    private final UserServiceImp userServiceImp;    public UserController(UserServiceImp userServiceImp) {        this.userServiceImp = userServiceImp;    }    @PostMapping("/{id}")    public ResponseEntity<UserResponseDTO> createUser (@Valid @RequestBody UserRequestDTO dto){        UserResponseDTO responseDTO = userServiceImp.createUser(dto);        return ResponseEntity.status(HttpStatus.CREATED).body(responseDTO);    }    @PostMapping ("/bulk")    public ResponseEntity<List<UserResponseDTO>> createUsers (@Valid @RequestBody List<UserRequestDTO> dtos){        List<UserResponseDTO> responseDTOS = userServiceImp.createUsers(dtos);        return ResponseEntity.status(HttpStatus.CREATED).body(responseDTOS);    }    @GetMapping ("/{id}")    public ResponseEntity<Optional<UserResponseDTO>> getUser (@PathVariable Long id){        Optional<UserResponseDTO> responseDTO = userServiceImp.getUser(id);        return ResponseEntity.ok(responseDTO);    }    @GetMapping ("/all")    public ResponseEntity<PagedResponse<UserResponseDTO>> getAllUsers (@RequestParam(required = false) String search,                                                                       @RequestParam (defaultValue = "10") int size,                                                                       @RequestParam (defaultValue = "0") int page,                                                                       @RequestParam (defaultValue = "DESC")SortDirection sortDirection,                                                                       @RequestParam (defaultValue = "ID")UserSortField userSortField){        PagedResponse<UserResponseDTO> response = userServiceImp.getAllUsers(search,size,page,userSortField,sortDirection);        return ResponseEntity.ok(response);    }    @GetMapping ("/{ids}")    public ResponseEntity<Optional<List<UserResponseDTO>>> getUsersById (@PathVariable List<Long>ids){        Optional<List<UserResponseDTO>> responseDTOS = userServiceImp.getUsersById(ids);        return ResponseEntity.ok(responseDTOS);    }    @PutMapping ("/{id}")    public ResponseEntity<Optional<UserResponseDTO>> updateUser (@PathVariable Long id,@RequestBody UserRequestDTO dto){        Optional<UserResponseDTO> responseDTO = userServiceImp.updateUser(id,dto);        return ResponseEntity.status(HttpStatus.OK).body(responseDTO);    }    @DeleteMapping ("/{id}")    public ResponseEntity<Void> deleteUser (@PathVariable Long id,@RequestParam boolean confirm){        userServiceImp.deleteUser(id,confirm);        return ResponseEntity.noContent().build();    }    @DeleteMapping ("/all")    public ResponseEntity<Void> deleteAll (@RequestParam boolean confirm){        userServiceImp.deleteAll(confirm);        return ResponseEntity.noContent().build();    }    @DeleteMapping("/{ids}")    public ResponseEntity<List<Void>> deleteByIds (@PathVariable List<Long>ids, @RequestParam boolean confirm){        userServiceImp.deleteById(ids,confirm);        return ResponseEntity.noContent().build();    }}